import React, { useState } from 'react';
import { BrowserRouter as Router, Route, Routes, useNavigate } from 'react-router-dom';
import ResumeForm from './components/resume';
import PopUp from './components/Contact'; 
import LoginPage from './components/LoginPage';





function App() {
    const [isModalOpen, setIsModalOpen] = useState(false);



    // Open and close modal functions
    const openModal = () => setIsModalOpen(true);
    const closeModal = () => setIsModalOpen(false);

    return (
        <Router>
            <div className="App">
                {/* Routes */}
                <Routes>
                    <Route
                        path="/"
                        element={<ResumeForm openModal={openModal} />}
                    />
                    <Route
                        path="/login"
                        element={<LoginPage />}
                    />
                </Routes>

                {/* "About Me" Modal */}
                <PopUp isOpen={isModalOpen} onClose={closeModal} title="About Me">
                    <p>Developed by Annie Rome</p>
                    <p>Sign Up to save you progress, all users are stored in a Mongodb backend with an encrypted password</p>
                    <p>
                        Check out my portfolio here:{" "}
                        <a href="https://www.anniecaroline.com/" target="_blank" rel="noopener noreferrer">
                            My Portfolio
                        </a>
                    </p>
                </PopUp>
            </div>
        </Router>
    );
}

export default App;
